llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C56"],
      "claim": "Dapagliflozin, with a high assay-transfer score, has absolute oral bioavailability of 78% (90% CI 73–83%) in healthy subjects, well above the 20% threshold."
    },
    {
      "card_ids": ["C03"],
      "claim": "Propranolol, with a high assay-transfer score, has a weighted mean oral extent of bioavailability of 32.9% (range 22–46%) in humans, supporting F ≥ 20%; similar high numeric values are seen for indomethacin, encainide, metoclopramide, diphenhydramine, bumetanide, metoprolol, and tolfenamic acid."
    },
    {
      "card_ids": ["C96"],
      "claim": "Verapamil is the only mixed evidence: a study in 20 normal young men reported mean absolute bioavailability of 19.4% after oral doses, below the 20% threshold, while other verapamil records report 22–24%."
    }
  ],
  "confidence": "moderate",
  "contradictory_card_ids": ["C96"],
  "decision_summary": "Nine of ten high-transfer evidence molecules show absolute oral bioavailability values above 20% in ordinary adult conditions; only verapamil is mixed with some values below 20%. The overall evidence supports high bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "Molecule 1 includes a provenance conflict: C02 refers to lisuride, not the same compound as the other propranolol records; it was discounted.",
    "Qualitative 'low bioavailability' statements (C19, C37, C48) lack threshold-specific numeric values and were not used as negative evidence.",
    "Special-population and altered-condition records (infants, premature infants, cirrhosis, elderly, sustained-release/microdose) were discounted for ordinary-condition comparison.",
    "Verapamil values straddle the 20% threshold, adding uncertainty."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C56", "C03"],
  "revision_action": "initial",
  "supportive_card_ids": ["C56", "C03"]
}

